// "How hard can a promise be? It's just a callback holder."
// This is the naive version everyone writes first. It LOOKS right
// and works for exactly one demo, then lies to you four ways.

function MyPromise(executor) {
  var self = this;
  self.callbacks = [];
  self.value = undefined;

  executor(function resolve(value) {
    // Problem 1: no state. Resolve twice? Callbacks run TWICE.
    // Real promises settle exactly once, forever.
    self.value = value;
    for (var i = 0; i < self.callbacks.length; i++) {
      // Problem 2: callbacks run SYNCHRONOUSLY, inside resolve().
      // Real `then` callbacks always run on the microtask queue —
      // subscribe-before-vs-after-settle must not change behavior,
      // and code after .then() must run before the handler does.
      self.callbacks[i](value);
    }
  }, function reject() {
    // Problem 3: rejection is... not implemented. Errors thrown in
    // the executor or handlers just explode up whatever stack
    // happens to be running. No .catch, no propagation.
  });
}

MyPromise.prototype.then = function (onFulfilled) {
  // Problem 4: subscribe AFTER it settled? Straight into the array
  // nobody will ever loop over again. The callback never fires.
  // (This is the bug you hit the moment a promise resolves fast.)
  this.callbacks.push(onFulfilled);

  // Problem 5: returns NOTHING. No chaining: p.then(a).then(b) is
  // a TypeError. And a handler's return value goes nowhere, so
  // transforming values through a pipeline is impossible.
};

// It demos fine — which is exactly why people ship it:
var p = new MyPromise(function (resolve) {
  setTimeout(function () { resolve(42); }, 10);
});
p.then(function (v) { console.log("got", v); });

// ...but:
var settled = new MyPromise(function (resolve) { resolve("early"); });
settled.then(function (v) { console.log("this NEVER prints:", v); });

# 🏋️ Practice: MyPromise

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

The README leaves `finally` and the static combinators "as exercises" — here they are. You don't need to edit `my-promise.js`: in a scratch file, `import { MyPromise } from './refactored/my-promise.js'` and attach your additions from outside (`MyPromise.prototype.finally = ...`, `MyPromise.all = ...`). Everything must be buildable from the public pieces: `then`, `catch`, `MyPromise.resolve/reject`, `new MyPromise(executor)`. Runs offline with `node` — and note you can `await` a MyPromise directly, because `await` adopts any thenable.

## Exercises

### ⭐ 1. Resolve-with-a-promise flattens (warm-up)

Write a test showing that `MyPromise.resolve(innerPromise)` gives you the inner promise's *value*, not a promise-in-a-promise. Make the inner one settle late (a `setTimeout`) so you prove adoption waits.

What it practices: thenable adoption — the rule `#resolveWith` implements.
Expected: `await MyPromise.resolve(inner)` is `5` (not a MyPromise object), even though `inner` resolves 10 ms later.
Hint: build `inner` with `new MyPromise(resolve => setTimeout(() => resolve(5), 10))`.

### ⭐⭐ 2. `finally(onFinally)`

Implement `finally`: runs the callback whether the promise fulfilled or rejected, **passes the original outcome through** (value stays, reason still throws), and if `onFinally` itself throws, *that* error wins. Bonus rule (the real spec's): if `onFinally` returns a promise, wait for it before passing the outcome on.

What it practices: building a new combinator purely out of `then` — no access to private state needed.
Expected: `MyPromise.resolve(7).finally(() => log.push('cleanup'))` resolves `7`; a rejected chain still rejects with the *original* error after cleanup ran; a throwing `onFinally` replaces the outcome with its own rejection.
Hint: two-handler `then`; in each handler run `onFinally()`, wrap it in `MyPromise.resolve(...)`, and chain the pass-through after it.

### ⭐⭐ 3. `MyPromise.all(items)`

Implement `all`: resolves with an array of values **in input order** (not settle order), rejects with the first rejection, and resolves `[]` for an empty array. Mix a slow item, a fast item, and a plain non-promise value in your test.

What it practices: coordinating N promises with a counter in a closure — and why the microtask queue makes that counter safe.
Expected: `await MyPromise.all([slow10msA, fastB, 'plain'])` is `['A', 'B', 'plain']`; if one item rejects, the whole thing rejects with that error.
Hint: `values[i] = v` with the loop's own index, plus a `remaining` counter; resolve when it hits 0. `MyPromise.resolve(item)` normalizes plain values.

### ⭐⭐ 4. `MyPromise.race(items)`

Implement `race`: settles exactly like the *first* item to settle, value or error. Then answer in a comment: why does the "loser" calling `resolve` later cause no bug, with no extra guard code from you?

What it practices: seeing the settle-once state machine do the work — the guard you built in the constructor *is* the feature.
Expected: fast rejection beats slow fulfillment → `race` rejects with the fast error; swap the speeds → it fulfills.
Hint: the whole body is one loop calling `.then(resolve, reject)` on each item. That's not a trick — that's the point.

### ⭐⭐⭐ 5. `MyPromise.any(items)`

Implement `any`: fulfills with the **first fulfillment**; rejects only if *all* items reject, with an `AggregateError` whose `errors` array holds every reason **in input order**. An empty input rejects immediately with an empty `AggregateError`.

What it practices: the mirror image of `all` — count rejections instead of fulfillments, and keep per-slot bookkeeping for the error report.
Expected: `[rejectFast, fulfillSlow('ok')]` → fulfills `'ok'`; `[rejectA, rejectB]` → rejects with `err.errors.map(e => e.message)` equal to `['A', 'B']` even if B rejected first.
Hint: `errors[i] = reason` (input order!), `remaining--`, reject with `new AggregateError(errors, ...)` at 0. First fulfillment just calls `resolve` — settle-once ignores the rest.

## Solutions

### 1. Adoption test

```js
const inner = new MyPromise((resolve) => setTimeout(() => resolve(5), 10));
const outer = MyPromise.resolve(inner);
assert.equal(await outer, 5);
```

WHY: `MyPromise.resolve(inner)` hands `inner` to `#resolveWith`, which finds a callable `.then` and *adopts* — the outer promise stays pending until the inner one settles, then takes its value. That single rule is why chains flatten instead of nesting, and this test shows it working across real time, not just synchronously.

### 2. `finally`

```js
MyPromise.prototype.finally = function (onFinally) {
  return this.then(
    (value) => MyPromise.resolve(onFinally()).then(() => value),
    (reason) => MyPromise.resolve(onFinally()).then(() => { throw reason; }),
  );
};
```

```js
const log = [];
assert.equal(await MyPromise.resolve(7).finally(() => log.push('cleanup')), 7);
await MyPromise.reject(new Error('boom'))
  .finally(() => log.push('cleanup2'))
  .catch((e) => log.push('caught ' + e.message));
// log: ['cleanup', 'cleanup2', 'caught boom']
```

WHY: `finally` is pure composition — both `then` handlers run the callback, then re-emit the original outcome (`() => value` or re-`throw reason`). Wrapping `onFinally()`'s return in `MyPromise.resolve` makes a returned thenable delay the pass-through (adoption again), and if `onFinally` throws, the throw happens inside a handler, which — by the machinery you built — rejects the next promise, correctly replacing the outcome.

### 3. `MyPromise.all`

```js
MyPromise.all = function (items) {
  return new MyPromise((resolve, reject) => {
    const values = [];
    let remaining = 0;
    let index = 0;
    for (const item of items) {
      const i = index++;
      remaining++;
      MyPromise.resolve(item).then((v) => {
        values[i] = v;
        if (--remaining === 0) resolve(values);
      }, reject);
    }
    if (index === 0) resolve([]);
  });
};
```

```js
const slow = new MyPromise((r) => setTimeout(() => r('A'), 10));
assert.deepEqual(await MyPromise.all([slow, MyPromise.resolve('B'), 'plain']),
  ['A', 'B', 'plain']);
await MyPromise.all([MyPromise.reject(new Error('bad')), slow])
  .catch((e) => assert.equal(e.message, 'bad'));
assert.deepEqual(await MyPromise.all([]), []);
```

WHY: `values[i] = v` stores by *input slot*, so order is by position, not by finish time. The `remaining` counter is safe from a subtle race because of exercise-0 knowledge: handlers run on the microtask queue, never synchronously inside `then`, so the loop finishes incrementing before any handler can decrement — your own `#schedule` guarantees it. Any rejection calls `reject` directly, and settle-once makes later results no-ops.

### 4. `MyPromise.race`

```js
MyPromise.race = function (items) {
  return new MyPromise((resolve, reject) => {
    for (const item of items) MyPromise.resolve(item).then(resolve, reject);
  });
};
```

```js
const slowWin = new MyPromise((r) => setTimeout(() => r('slow'), 30));
const fastFail = new MyPromise((_, j) => setTimeout(() => j(new Error('fast')), 5));
await MyPromise.race([slowWin, fastFail]).catch((e) => assert.equal(e.message, 'fast'));
```

WHY: every item gets to call `resolve` or `reject`, but the constructor's `settled` guard means only the first call counts — the losers' later calls hit `if (settled) return` and vanish. No extra bookkeeping is needed because the state machine already enforces "one way, one time". `race` is the exercise that proves the guard isn't defensive clutter; it's load-bearing API.

### 5. `MyPromise.any`

```js
MyPromise.any = function (items) {
  return new MyPromise((resolve, reject) => {
    const errors = [];
    let remaining = 0;
    let index = 0;
    for (const item of items) {
      const i = index++;
      remaining++;
      MyPromise.resolve(item).then(resolve, (reason) => {
        errors[i] = reason;
        if (--remaining === 0) {
          reject(new AggregateError(errors, 'All promises were rejected'));
        }
      });
    }
    if (index === 0) reject(new AggregateError([], 'All promises were rejected'));
  });
};
```

```js
const ok = new MyPromise((r) => setTimeout(() => r('ok'), 10));
assert.equal(await MyPromise.any([MyPromise.reject(new Error('no')), ok]), 'ok');
await MyPromise.any([MyPromise.reject(new Error('A')), MyPromise.reject(new Error('B'))])
  .catch((e) => assert.deepEqual(e.errors.map((x) => x.message), ['A', 'B']));
```

WHY: `any` mirrors `all` with the roles swapped — fulfillments short-circuit via bare `resolve` (settle-once absorbs duplicates), rejections are *counted and recorded by slot* so the final `AggregateError` reports every failure in input order regardless of timing. It reuses all three of the project's big ideas at once: adoption (`MyPromise.resolve(item)` normalizes anything), microtask scheduling (the counter can't race the loop), and the settle-once state machine (first fulfillment wins cleanly).

/**
 * MyPromise — a real Promise implementation: settle-once state
 * machine, microtask-scheduled handlers, chaining, error
 * propagation, and thenable adoption. (The core of the Promises/A+
 * spec; `finally`/`all`/cancellation left as exercises.)
 *
 * The mental model that makes it all click:
 *
 *   A promise is a STATE MACHINE (project 40):
 *     pending -> fulfilled(value)     (one way, one time)
 *     pending -> rejected(reason)
 *
 *   `then` NEVER runs anything now. It registers a REACTION and
 *   returns a NEW promise that the reaction will settle later.
 *   Chaining is just promises settling promises.
 */

const PENDING = 'pending';
const FULFILLED = 'fulfilled';
const REJECTED = 'rejected';

export class MyPromise {
  #state = PENDING;
  #result = undefined;   // value when fulfilled, reason when rejected
  #reactions = [];       // queued {onFulfilled, onRejected, settleNext}

  constructor(executor) {
    // Bind once; guard so resolve/reject TOGETHER can only win once.
    let settled = false;
    const resolve = (value) => {
      if (settled) return; // Problem 1's fix: settling is final
      settled = true;
      this.#resolveWith(value);
    };
    const reject = (reason) => {
      if (settled) return;
      settled = true;
      this.#settle(REJECTED, reason);
    };

    try {
      executor(resolve, reject);
    } catch (err) {
      reject(err); // a throwing executor is just a rejection
    }
  }

  /**
   * Resolving is not the same as fulfilling: if `value` is itself a
   * promise (or any object with a callable .then — a "thenable"),
   * we ADOPT its eventual state instead of fulfilling with it.
   * This one rule is why `return anotherPromise` inside .then()
   * flattens instead of nesting.
   */
  #resolveWith(value) {
    const then = value !== null && (typeof value === 'object' || typeof value === 'function')
      ? value.then
      : undefined;

    if (typeof then !== 'function') return this.#settle(FULFILLED, value);

    let adopted = false; // a misbehaving thenable may call back twice
    try {
      then.call(
        value,
        (v) => { if (!adopted) { adopted = true; this.#resolveWith(v); } },
        (r) => { if (!adopted) { adopted = true; this.#settle(REJECTED, r); } },
      );
    } catch (err) {
      if (!adopted) this.#settle(REJECTED, err);
    }
  }

  #settle(state, result) {
    this.#state = state;
    this.#result = result;
    const reactions = this.#reactions;
    this.#reactions = []; // deliver each reaction exactly once
    for (const reaction of reactions) this.#schedule(reaction);
  }

  /**
   * Handlers ALWAYS run on the microtask queue — never synchronously
   * inside resolve() or inside then(). This is what makes
   * subscribe-before-settle and subscribe-after-settle behave
   * identically, and guarantees code after `.then(...)` runs before
   * the handler does.
   */
  #schedule(reaction) {
    queueMicrotask(() => {
      const handler = this.#state === FULFILLED ? reaction.onFulfilled : reaction.onRejected;
      if (typeof handler !== 'function') {
        // No handler for this outcome: pass the result THROUGH.
        // (This hole in the chain is how errors skip past .then(fn)
        // blocks and land in the .catch at the end.)
        reaction.settleNext(this.#state, this.#result);
        return;
      }
      try {
        reaction.settleNext(FULFILLED, handler(this.#result)); // may be a thenable -> adopted
      } catch (err) {
        reaction.settleNext(REJECTED, err); // a throwing handler rejects the NEXT promise
      }
    });
  }

  then(onFulfilled, onRejected) {
    let settleNext;
    const next = new MyPromise((resolve, reject) => {
      settleNext = (state, result) => (state === FULFILLED ? resolve(result) : reject(result));
    });

    const reaction = { onFulfilled, onRejected, settleNext };
    if (this.#state === PENDING) this.#reactions.push(reaction);
    else this.#schedule(reaction); // already settled: late subscribers still fire

    return next;
  }

  catch(onRejected) {
    return this.then(undefined, onRejected);
  }

  static resolve(value) {
    return new MyPromise((resolve) => resolve(value));
  }

  static reject(reason) {
    return new MyPromise((_, reject) => reject(reason));
  }
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { MyPromise } from './my-promise.js';

// MyPromise is a thenable, so real await works on it — the tests
// exercise MyPromise THROUGH the platform's own async machinery.

test('resolves asynchronously', async () => {
  const p = new MyPromise((resolve) => setTimeout(() => resolve(42), 5));
  assert.equal(await p, 42);
});

test('LATE subscribers fire too (the original\'s never-prints bug)', async () => {
  const p = new MyPromise((resolve) => resolve('early'));
  await new Promise((r) => setTimeout(r, 5)); // long after settling
  assert.equal(await p.then((v) => v + '!'), 'early!');
});

test('settling is final: second resolve/reject are ignored', async () => {
  let calls = 0;
  const p = new MyPromise((resolve, reject) => {
    resolve(1);
    resolve(2);       // ignored
    reject(new Error('too late')); // ignored
  });
  p.then(() => calls++);
  await new Promise((r) => setTimeout(r, 5));
  assert.equal(calls, 1);
  assert.equal(await p, 1);
});

test('handlers run on the microtask queue, never synchronously', async () => {
  const order = [];
  const p = MyPromise.resolve('x');
  p.then(() => order.push('handler'));
  order.push('after then'); // must run FIRST — then() never runs anything now
  await p;
  await new Promise((r) => setTimeout(r, 0));
  assert.deepEqual(order, ['after then', 'handler']);
});

test('chaining transforms values through a pipeline', async () => {
  const result = await MyPromise.resolve(2)
    .then((n) => n * 10)
    .then((n) => n + 1);
  assert.equal(result, 21);
});

test('a handler returning a MyPromise is ADOPTED (flattening, not nesting)', async () => {
  const result = await MyPromise.resolve('a')
    .then((v) => new MyPromise((resolve) => setTimeout(() => resolve(v + 'b'), 5)))
    .then((v) => v + 'c');
  assert.equal(result, 'abc');
});

test('a throwing executor rejects', async () => {
  await assert.rejects(
    async () => { await new MyPromise(() => { throw new Error('boom'); }); },
    /boom/,
  );
});

test('a throwing HANDLER rejects the next promise in the chain', async () => {
  await assert.rejects(
    async () => {
      await MyPromise.resolve(1).then(() => { throw new Error('mid-chain'); });
    },
    /mid-chain/,
  );
});

test('errors SKIP fulfillment handlers and land in catch', async () => {
  const hops = [];
  const result = await MyPromise.reject(new Error('original failure'))
    .then((v) => { hops.push('skipped 1'); return v; })
    .then((v) => { hops.push('skipped 2'); return v; })
    .catch((err) => `caught: ${err.message}`);
  assert.deepEqual(hops, []);
  assert.equal(result, 'caught: original failure');
});

test('catch RECOVERS: the chain continues fulfilled after it', async () => {
  const result = await MyPromise.reject(new Error('x'))
    .catch(() => 'recovered')
    .then((v) => v + ' and continued');
  assert.equal(result, 'recovered and continued');
});

test('then with non-function args passes values through (the chain hole)', async () => {
  assert.equal(await MyPromise.resolve(7).then().then(null, () => 'nope'), 7);
});

test('adopts a plain thenable (not just MyPromise instances)', async () => {
  const thenable = { then: (resolve) => setTimeout(() => resolve('from thenable'), 5) };
  assert.equal(await MyPromise.resolve(thenable), 'from thenable');
});

test('a misbehaving thenable that calls resolve twice settles once', async () => {
  let calls = 0;
  const sneaky = { then: (resolve) => { resolve('first'); resolve('second'); } };
  const p = MyPromise.resolve(sneaky);
  p.then(() => calls++);
  await new Promise((r) => setTimeout(r, 5));
  assert.equal(calls, 1);
  assert.equal(await p, 'first');
});
